        var _MAX_URL_LEN         = 2048; // max absolute URL length per field
        var _MAX_ROUTE_LEN       = 1024; // max Base-relative endpoint route
        var _MAX_HOST_LEN        = 253;  // RFC-style DNS presentation limit
