                        base:        p.base        || '',
                        chat:        p.chat        || '',
                        share:       p.share       || '',
                        feedback:    p.feedback    || '',
                        training:    p.training    || '',
                        datasetRepo: p.datasetRepo || '',
                        ttlDays:     p.ttlDays     || 30,
