        var h = 5381;
        for (var i = 0; i < str.length; i++) {
            h = ((h << 5) + h) ^ str.charCodeAt(i);
            h = h & h;          // force 32-bit signed integer
        }
        var hex = (h >>> 0).toString(16);
        while (hex.length < 8) { hex = '0' + hex; }
        return hex;
