            var match = path.match(/^(.*\/v1\/share)\/((?:[0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}))$/i);
            if (!id && match) { id = match[2]; path = match[1]; }
